INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 22, 'theory', 'Quiz: modules, tests and cargo');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 22, 0, 'What does the absence of pub before a function in a module mean?', '["The function is open to everyone", "The function is visible only in its own module and its child modules", "The function is visible across the whole crate", "The function does not compile"]', 1, 'In Rust everything is private by default. pub(crate) opens it within the crate, pub opens it to the outside.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 22, 1, 'What is the Cargo.lock file for?', '["Storing documentation", "Locking parallel builds", "Describing features", "Pinning the exact versions of dependencies so that builds are reproducible"]', 3, 'Cargo.toml holds compatibility ranges, while the lock file remembers the concrete choice along with checksums.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 22, 2, 'How do integration tests in the tests/ folder differ from unit tests?', '["They don''t", "They are faster", "Each file is a separate crate that sees only the library''s pub interface", "They see private functions"]', 2, 'A unit test is a child module and sees private items, while an integration test links the library as an outside user.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 22, 3, 'What does pub use do in lib.rs?', '["Exports an item under a short public path, keeping the internal structure private", "Imports a foreign crate", "Makes the whole module public", "Turns off the visibility check"]', 0, 'A re-export shapes the public interface: the user does not depend on the internal file layout.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 22, 4, 'How can you check that your tests are able to find a bug at all?', '["Run them several times", "Add more asserts", "Turn on release mode", "Deliberately break the implementation and make sure at least one test fails"]', 3, 'This is mutation testing. A test that stays green on broken code checks nothing.');
